mapper.select:
SELECT
    x.attachment_id AS attachmentId,
    x.business_type AS businessType,
    x.business_id AS businessId,
    x.business_name AS businessName,
    x.file_type AS fileType,
    x.file_category AS fileCategory,
    x.file_name AS fileName,
    x.file_size AS fileSize,
    x.file_format AS fileFormat,
    x.version_no AS versionNo,
    x.is_latest AS isLatest,
    NULL AS uploadUserName,
    x.upload_user_id AS uploadUserId,
    x.upload_time AS uploadTime,
    x.download_count AS downloadCount,
    x.file_status AS fileStatus,
    x.security_level AS securityLevel,
    NULL AS createdByName,
    x.created_by AS createdBy,
    x.created_time AS createdTime
FROM (

) x


        AND x.business_type = #{req.businessType}


        AND x.business_id = #{req.businessId}


        AND x.file_type = #{req.fileType}


        AND 1 = 0


        AND x.file_name LIKE CONCAT('%', #{req.fileName}, '%')


        AND x.file_format = #{req.fileFormat}


        AND x.upload_user_id = #{req.uploadUserId}


        AND x.security_level = #{req.securityLevel}


        AND x.file_status = #{req.fileStatus}


        AND x.upload_time >= #{req.uploadTimeStart}


        AND x.upload_time <= #{req.uploadTimeEnd}


        AND x.created_by = #{req.createdBy}


        AND x.created_time >= #{req.createdTimeStart}


        AND x.created_time <= #{req.createdTimeEnd}


ORDER BY x.created_time DESC

SELECT COALESCE(SUM(cnt), 0) FROM (
    SELECT COUNT(1) AS cnt
    FROM exp_tender_attachment
    WHERE #{businessType} = 'TENDER'
      AND tender_id = #{businessId}
      AND file_name = #{fileName}
    UNION ALL
    SELECT COUNT(1) AS cnt
    FROM exp_bid_attachment
    WHERE #{businessType} = 'BID'
      AND bid_id = #{businessId}
      AND file_name = #{fileName}
) s

choose.when:
SELECT attachment_id
FROM exp_tender_attachment
WHERE tender_id = #{businessId}
  AND file_name = #{fileName}
  AND upload_user_id = #{uploadUserId}
ORDER BY attachment_id DESC
LIMIT 1

SELECT attachment_id
FROM exp_bid_attachment
WHERE bid_id = #{businessId}
  AND file_name = #{fileName}
  AND upload_user_id = #{uploadUserId}
ORDER BY attachment_id DESC
LIMIT 1
